      "instruction": "Mettez en ordre le dialogue suivant et récrivez : Le marchand : Regardez aussi des tomates, elles sont belles ! La cliente : Oui. Merci ! Le marchand : Alors, un kilo de pommes de terre et un kilo de tomates … ça ira ? La cliente : Je voudrais des pommes de terre. Un kilo s’il vous plaît. Le marchand : Bonjour, qu’est-ce qu’il vous faudra ? La cliente : Oui... elles sont bonnes… donnez-moi un kilo.",
