      "instruction": "Mettez en ordre le dialogue suivant et récrivez : Directeur : Ah oui, le voilà. Merci. Et, Monsieur Dubois, a-t-il confirmé notre rendez-vous ? Secrétaire : Je crois qu’il est sur votre bureau. Où il est peut-être sous un autre dossier ... Directeur : Marie, avez-vous vu mon dossier personnel ? Secrétaire : Je l’ai appelé et j’ai laissé un message ... Vous voulez que je le rappelle ? Directeur : Oui, dites-lui que je serais un peu en retard.",
      "marks": 5,
