      "id": "qp2020-1",
      "num": "1",
      "instruction": "Regardez l’image, et lisez le texte pour répondre aux questions. (5 au choix) 10 Le Québec .20 2 Le Québec est situé au nord-est du continent américain. Il est la plus grande province du Canada. Voisin des États-unis au sud et de l’Ontario à l’ouest, la grande majorité de la population vit aux abords du fleuve Saint-Laurent. Le Saint-Laurent est l’un des grands fleuves du globe. Les Québécois sont, en général, fiers d’être francophones, même s’ils sont minoritaires dans un Canada anglophone. Le français est la langue officielle du Québec, mais c’est une province qui est bilingue : l’anglais y coexiste avec le français. Montréal est la plus importante région touristique du Québec, ayant reçu 8,4 millions de touristes en 2013. La ville de Québec est la seule ville fortifiée en Amérique du Nord. Elle est la capitale. Étant la plus vieille ville francophone d’Amérique, l’arrondissement historique du Vieux-Québec a d’ailleurs été déclaré site du patrimoine mondial par l’Unesco en 1985. Répondez (5 au choix) :",
