      "answer": "Cher oncle,\nNous fêtons le 50e anniversaire de mariage de nos grands-parents samedi 12 mars à dix-neuf heures, à la maison. Toute la famille sera là et nous aimerions beaucoup que tu viennes avec ta femme et les enfants. Ce sera une surprise pour eux, alors ne dis rien !\nRéponds-nous vite. Affectueusement, Meera",
      "flags": [],
