     {
      "id": "qp2020-3c",
      "num": "3(c)",
      "instruction": "Complétez le texte en utilisant les mots / les expressions donnés : (États-Unis / danses / danseurs / accessible / mélange / enseignent / beaucoup de / énergie / D’ailleurs / sentiments) Le modern Jazz Le modern jazz est un __________ de plusieurs danses comme le jazz, la danse classique, la danse moderne, la danse africaine, les claquettes et la danse espagnole. Et c’est une des raisons pour laquelle il attire : par sa diversité, le modern jazz convient à __________ personnalités. Il laisse beaucoup de liberté aux __________ tout en étant technique. Elle demande de la souplesse, de la rigueur et de I’ __________ . Comme toutes les __________, elle permet l’expression des __________ . Le nom de cette danse est apparu dans les années 50 aux __________ . Le modern Jazz est __________ à tout âge et pour tous les niveaux. __________, vous pouvez trouver des cours près de chez vous sans problémes, presque tous les studios de danse __________ le modern jazz. .",
      "marks": 5,
      "choose": null,
      "isAlternative": false,
      "items": [],
      "topics": [
       {
        "key": "ex-story",
        "label": "Completing a story",
        "group": "expression",
        "deck": null,
        "confidence": "certain",
        "legacy": false
       }
      ],
      "answer": "Le modern jazz est un mélange de plusieurs danses comme le jazz, la danse classique, la danse moderne, la danse africaine, les claquettes et la danse espagnole. Et c’est une des raisons pour laquelle il attire : par sa diversité, le modern jazz convient à beaucoup de personnalités. Il laisse beaucoup de liberté aux danseurs tout en étant technique. Elle demande de la souplesse, de la rigueur et de l’énergie. Comme toutes les danses, elle permet l’expression des sentiments. D’ailleurs, le nom vient des États-Unis, où on l’enseigne dans beaucoup d’écoles.",
      "flags": [],
      "isContainer": false,
      "answerTier": "modele",
      "answerRubric": "libre",
      "leaf": "ex-story",
      "group": "expression"
     }
