      "isAlternative": false,
      "isContainer": false,
      "items": [
       {
        "label": "i",
        "text": "Aujourd’hui, pourquoi est-il important d’apprendre plusieurs langues ?",
        "missing": false,
        "flags": [
         "read-from-pdf"
        ],
        "page": 4,
        "answer": "Nous sommes aujourd’hui dans un processus de mondialisation : il y a plus d’échanges économiques, diplomatiques, culturels ou commerciaux entre les différentes régions du globe, donc un besoin de communication entre les différentes populations mondiales est fort nécessaire.",
        "answerTier": "modele"
       },
       {
        "label": "ii",
        "text": "Pensez-vous que les petits enfants bénéficient d’apprendre des langues étrangères ? Justifiez votre réponse.",
        "missing": false,
        "flags": [
         "read-from-pdf"
        ],
        "page": 4,
        "answer": "Oui. L’enseignement d’une seconde langue aux enfants dès l’école primaire, même maternelle, cherche à développer plus de tolérance vers les autres dans une société moderne d’aujourd’hui.",
        "answerTier": "modele"
       },
       {
        "label": "iii",
        "text": "Quels sont les avantages de connaître une langue étrangère quand on voyage ?",
        "missing": false,
        "flags": [
         "read-from-pdf"
        ],
        "page": 4,
        "answer": "Apprendre une langue étrangère permet de voyager beaucoup plus facilement et de découvrir le monde soi-même. Maîtriser la langue locale permet aussi de communiquer avec des personnes qui ne parlent pas forcément l’anglais.",
        "answerTier": "modele"
       }
      ],
