      "answer": "Tout le monde aime les centres commerciaux. En été comme en hiver, les gens visitent ces endroits fantastiques remplis de boutiques variées et d’animations diverses. En effet, même si vous ne voulez pas acheter quelque chose, il est toujours intéressant de passer du temps dans les centres commerciaux. Le centre commercial est l’endroit idéal pour passer un bon moment avec la famille ou des amis. Les gens y vont surtout pour déguster un bon sandwich assis près de la fontaine ou tout en regardant un spectacle de danse.",
